def legal_page(path, h1, title):
    secs = PRIVACY if path == "privacy" else CONSENT
    parts = [hero([("Главная", "/"), (h1, None)], "Документ", h1, "Редакция от 20 ноября 2026 года.", audit_present=False, art=False, ctas=[("pxa-btn", "/contacts", "Связаться с нами")])]
    for n, (h2, paras) in enumerate(secs):
        parts.append(text_section(h2, paras, idn=f"pxa-t{n}", tint=(n % 2 == 1)))
    parts.append(footer())
    return page(path, title, h1 + " Proxy Agency", "site.css", "\n".join(parts), noindex=True)

